import{z as A,x as l,o as e,c as s,q as n,j as i,D as E,d as o,s as B,S as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"最优通货膨胀","description":"","frontmatter":{"title":"最优通货膨胀","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mt-optimal-inflation.md","filePath":"econ/mt-optimal-inflation.md","lastUpdated":1791413859000}'),p={name:"econ/mt-optimal-inflation.md"};function d(m,a,C,c,F,h){const r=l("Mermaid");return e(),s("div",null,[a[2]||(a[2]=n('<h1 id="最优通货膨胀" tabindex="-1">最优通货膨胀 <a class="header-anchor" href="#最优通货膨胀" aria-label="Permalink to &quot;最优通货膨胀&quot;">​</a></h1><div class="epigraph"><p>让持币的机会成本归零，最优通胀就该是负的；没有央行采用这个答案，因为下限和财政都不允许它。</p><footer>—— 据 Friedman, The Optimum Quantity of Money, 1969 整理</footer></div><p><a href="/econ/apt-map">上一课</a>把资产定价深化的课程收束：核的弯在哪、可观测对应物是什么、过不过 Hansen–Jagannathan 与发表后存活率两道闸门。定价回答的是收益从哪来；换到宏观政策，先要问的是目标——通胀目标为什么是 \\(2\\%\\) 而不是 \\(0\\%\\)，甚至不是负的？宏观课把目标当成给定，本课程的第一课专门问它：最优通货膨胀由什么决定。后面的政策规则、预期、QE 理论、数字货币与利率走廊，都默认你已经想清楚目标，再谈怎么实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>通胀的收益一面出奇地窄。居民与企业持有货币是为了支付，<a href="/econ/money-as-medium">货币层次与支付</a>里已给出：现金与准备金的回报近似为零，而其他资产按名义利率 \\(i\\) 计息，持币的机会成本就是 \\(i\\)。\\(i\\) 越高，人们越省着用货币：更快地把工资换成生息资产、更频繁地跑银行、把现金缓冲削得更薄。Friedman 1969 把这笔损耗画成三角形：货币需求向下倾斜，单位价格是 \\(i\\)，福利损失是价格线与需求曲线之间的面积。要把三角形消灭，只能令 \\(i=0\\)。</p><p><span class="marginnote">直觉类比：持币的机会成本像「货币的使用费」。费率越高，人们越少带现金、越频繁地跑银行——正如油费太贵的人宁可绕路少开车。Friedman 干脆主张把使用费降到零，让货币像一条免费的路。</span></p><p>成本一面则宽得多。可预期的通胀带来鞋底成本与<a href="/econ/menu-cost">菜单成本</a>，但温和水平下都不大；真正大的是相对价格分散——调价不同步，通胀越高，同一时刻各价格之间的错位越大；再加上税制不随通胀指数化的扭曲，与未预期通胀在债权债务之间的再分配。</p><p><span class="marginnote">数字实例：通胀 10% 的年份里，若一半价格每月才调一次，同一时刻同一种商品可能挂着相差好几个百分点的两个价——买家买贵、卖家定价失据。这种「错位」才是温和通胀的大头成本；鞋底成本（多跑几趟银行）只是零头。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把两面放进费雪方程 \\(i = r + \\pi^{e}\\)（<a href="/econ/fisher-equation">费雪方程</a>）。令 \\(i=0\\)，得到 <strong>Friedman 规则</strong>：通胀应等于真实利率的负值，\\(\\pi^{e} = -r\\)。若 \\(r\\) 在每年 \\(1\\%\\) 到 \\(2\\%\\)，最优通胀是每年 \\(-1\\%\\) 到 \\(-2\\%\\) 的温和通缩：价格缓慢下降，持币与持债一样好，货币的支付服务免费。</p><p>这个答案是基准，不是处方。推导只用了持币机会成本一件事，隐含三个前提：铸币税没有独立价值（<a href="/econ/seigniorage">通胀税与铸币税</a>的财政动机不存在）、名义利率下限不构成约束、价格分散与税制扭曲在温和通缩下不爆炸。哪一个前提松动，答案就往正通胀方向移动多少。</p>',11)),(e(),i(t,null,{default:E(()=>[B(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20COST%5B%22%E6%8C%81%E5%B8%81%E6%9C%BA%E4%BC%9A%E6%88%90%E6%9C%AC%20i%22%5D%20--%3E%20TRI%5B%22Friedman%20%E4%B8%89%E8%A7%92%E5%BD%A2%E6%8D%9F%E8%80%97%22%5D%0A%20%20TRI%20--%3E%20RULE%5B%22%E4%BB%A4%20i%3D0%EF%BC%9AFriedman%20%E8%A7%84%E5%88%99%22%5D%0A%20%20RULE%20--%3E%20FISHER%5B%22%E8%B4%B9%E9%9B%AA%E6%96%B9%E7%A8%8B%E7%BB%99%E5%87%BA%20pi%20%3D%20-r%22%5D%0A%20%20FISHER%20--%3E%20CHECK%7B%22%E4%B8%89%E4%B8%AA%E5%89%8D%E6%8F%90%E6%88%90%E7%AB%8B%E5%90%97%22%7D%0A%20%20CHECK%20--%3E%7C%22%E4%B8%8B%E9%99%90%E4%B8%8E%E8%B4%A2%E6%94%BF%E7%BA%A6%E6%9D%9F%E6%9D%BE%E5%8A%A8%22%7C%20UP%5B%22%E6%9C%80%E4%BC%98%E9%80%9A%E8%83%80%E4%B8%8A%E7%A7%BB%22%5D%0A%20%20CHECK%20--%3E%7C%22%E5%85%A8%E9%83%A8%E6%88%90%E7%AB%8B%22%7C%20DEF%5B%22%E6%B8%A9%E5%92%8C%E9%80%9A%E7%BC%A9%E4%B8%BA%E6%9C%80%E4%BC%98%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>现实央行全部把目标定在正的小值，偏离 Friedman 规则的机制有三个，值得逐一核对。</p><p>第一是<strong>下限</strong>。\\(\\pi = -r\\) 意味着名义利率长期贴着零，央行失去用利率应对衰退的常规空间。Eggertsson–Woodford 2003 在下限模型里证明：只要衰退可能发生，Friedman 规则不再最优——预留正的通胀与利率空间，等于买了一份对付下限的保险。这与<a href="/econ/zlb-unconventional">零下限与非常规政策</a>互为表里：那一课讲下限绑住工具后怎么办，本课讲为什么一开始就不该把工具绑死。</p><p>第二是<strong>财政</strong>。Sargent–Wallace 1981 的算术指出：若财政赤字独立于货币当局，今天的货币紧缩只是把通胀推迟并放大——最优通胀不是央行能单独决定的变量，它取决于财政与货币谁迁就谁。</p><p>第三是<strong>测量与缓冲</strong>。物价指数有向上偏差，\\(2\\%\\) 的目标对应的真实生活成本通胀接近零；正目标同时给相对价格调整留出空间，避免名义刚性全部由就业吸收。</p><p><span class="marginnote">Friedman 规则在 \\(r=2\\%\\) 时要求 \\(\\pi \\approx -2\\%\\)，没有任何主要央行采用。Eggertsson–Woodford 2003 给出最干净的反对理由：该规则把经济永久钉在利率下限上，冲击来临时没有工具可用——保险价值为负。</span></p><p><span class="marginnote">常见误区：以为零通胀「最稳妥」。在 Friedman 规则下零通胀仍是次优——持币仍有成本；而现实中反对零通胀的理由不是它太高，而是它太低：利率贴着下限，衰退来临时央行无工具可用。</span></p>',7)),(e(),i(t,null,{default:E(()=>[B(r,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20FR%5B%22Friedman%20%E8%A7%84%E5%88%99%EF%BC%9Api%20%3D%20-r%22%5D%20--%3E%20ZLB%5B%22%E6%9C%BA%E5%88%B6%E4%B8%80%EF%BC%9A%E4%B8%8B%E9%99%90%22%5D%0A%20%20FR%20--%3E%20FISC%5B%22%E6%9C%BA%E5%88%B6%E4%BA%8C%EF%BC%9A%E8%B4%A2%E6%94%BF%E9%93%B8%E5%B8%81%E7%A8%8E%22%5D%0A%20%20FR%20--%3E%20MEAS%5B%22%E6%9C%BA%E5%88%B6%E4%B8%89%EF%BC%9A%E6%B5%8B%E9%87%8F%E4%B8%8E%E7%BC%93%E5%86%B2%22%5D%0A%20%20ZLB%20--%3E%20Z1%5B%22%E9%A2%84%E7%95%99%E9%99%8D%E6%81%AF%E7%A9%BA%E9%97%B4%20%3D%20%E7%BB%99%E4%B8%8B%E9%99%90%E4%B9%B0%E4%BF%9D%E9%99%A9%22%5D%0A%20%20FISC%20--%3E%20F1%5B%22%E8%B4%A2%E6%94%BF%E4%B8%8D%E8%BF%81%E5%B0%B1%E5%88%99%E7%B4%A7%E7%BC%A9%E5%8F%AA%E6%8E%A8%E8%BF%9F%E9%80%9A%E8%83%80%22%5D%0A%20%20MEAS%20--%3E%20M1%5B%22%E6%8C%87%E6%95%B0%E4%B8%8A%E5%81%8F%20%2B%20%E7%95%99%E7%9B%B8%E5%AF%B9%E4%BB%B7%E6%A0%BC%E8%B0%83%E6%95%B4%E7%A9%BA%E9%97%B4%22%5D%0A%20%20Z1%20--%3E%20POS%5B%22%E7%8E%B0%E5%AE%9E%E7%9B%AE%E6%A0%87%E5%81%9C%E5%9C%A8%E6%AD%A3%E7%9A%84%E5%B0%8F%E5%80%BC%22%5D%0A%20%20F1%20--%3E%20POS%0A%20%20M1%20--%3E%20POS%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只谈确定环境下的稳态最优，不引入产出一通胀的短期交替——那是<a href="/econ/nk-phillips">新凯恩斯菲利普斯曲线</a>与<a href="/econ/optimal-nk-policy">最优货币政策</a>的对象。也不讨论 2.0 还是 2.5 个百分点这类精度：在异质家庭与金融摩擦下，最优目标对分布假设敏感，没有单一数字。Friedman 规则的价值在于给出方向：持币成本是政策变量，把它压低有真实收益，压过头的代价由下限与财政来计价。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>持币的机会成本是名义利率；Friedman 1969 据此推出最优通胀为负，\\(\\pi^{e}=-r\\)。</li><li>温和通胀的真实成本是相对价格分散与税制扭曲，不是鞋底成本。</li><li>下限约束、财政铸币税与测量缓冲，是现实目标停在正小值的三个机制。</li><li>目标的选择决定后课一切工具的空间：目标定得越低，下限绑得越早。</li><li>出处：Friedman, <em>The Optimum Quantity of Money</em>, 1969；Eggertsson–Woodford 2003；Sargent–Wallace 1981；Woodford, <em>Interest and Prices</em>, 2003。</li></ul>',4))])}const D=A(p,[["render",d]]);export{_ as __pageData,D as default};
